export interface AppointmentService {
  /** Book a new appointment */
  BookAppointment(request: BookAppointmentRequest): Promise<BookAppointmentResponse>;
  /** Update an existing appointment */
  UpdateAppointment(request: UpdateAppointmentRequest): Promise<UpdateAppointmentResponse>;
  /** Accept/confirm an appointment (doctors, employees, admins) */
  AcceptAppointment(request: AcceptAppointmentRequest): Promise<AcceptAppointmentResponse>;
  /** Cancel an appointment */
  CancelAppointment(request: CancelAppointmentRequest): Promise<CancelAppointmentResponse>;
  /** Get user's appointments with pagination */
  GetMyAppointments(request: GetMyAppointmentsRequest): Promise<GetMyAppointmentsResponse>;
}

export const AppointmentServiceServiceName = "appointment.AppointmentService";
export class AppointmentServiceClientImpl implements AppointmentService {
  private readonly rpc: Rpc;
  private readonly service: string;
  constructor(rpc: Rpc, opts?: { service?: string }) {
    this.service = opts?.service || AppointmentServiceServiceName;
    this.rpc = rpc;
    this.BookAppointment = this.BookAppointment.bind(this);
    this.UpdateAppointment = this.UpdateAppointment.bind(this);
    this.AcceptAppointment = this.AcceptAppointment.bind(this);
    this.CancelAppointment = this.CancelAppointment.bind(this);
    this.GetMyAppointments = this.GetMyAppointments.bind(this);
  }
  BookAppointment(request: BookAppointmentRequest): Promise<BookAppointmentResponse> {
    const data = BookAppointmentRequest.encode(request).finish();
    const promise = this.rpc.request(this.service, "BookAppointment", data);
    return promise.then((data) => BookAppointmentResponse.decode(new BinaryReader(data)));
  }

  UpdateAppointment(request: UpdateAppointmentRequest): Promise<UpdateAppointmentResponse> {
    const data = UpdateAppointmentRequest.encode(request).finish();
    const promise = this.rpc.request(this.service, "UpdateAppointment", data);
    return promise.then((data) => UpdateAppointmentResponse.decode(new BinaryReader(data)));
  }

  AcceptAppointment(request: AcceptAppointmentRequest): Promise<AcceptAppointmentResponse> {
    const data = AcceptAppointmentRequest.encode(request).finish();
    const promise = this.rpc.request(this.service, "AcceptAppointment", data);
    return promise.then((data) => AcceptAppointmentResponse.decode(new BinaryReader(data)));
  }

  CancelAppointment(request: CancelAppointmentRequest): Promise<CancelAppointmentResponse> {
    const data = CancelAppointmentRequest.encode(request).finish();
    const promise = this.rpc.request(this.service, "CancelAppointment", data);
    return promise.then((data) => CancelAppointmentResponse.decode(new BinaryReader(data)));
  }

  GetMyAppointments(request: GetMyAppointmentsRequest): Promise<GetMyAppointmentsResponse> {
    const data = GetMyAppointmentsRequest.encode(request).finish();
    const promise = this.rpc.request(this.service, "GetMyAppointments", data);
    return promise.then((data) => GetMyAppointmentsResponse.decode(new BinaryReader(data)));
  }
}

interface Rpc {
  request(service: string, method: string, data: Uint8Array): Promise<Uint8Array>;
}

type Builtin = Date | Function | Uint8Array | string | number | boolean | undefined;

export type DeepPartial<T> = T extends Builtin ? T
  : T extends globalThis.Array<infer U> ? globalThis.Array<DeepPartial<U>>
  : T extends ReadonlyArray<infer U> ? ReadonlyArray<DeepPartial<U>>
  : T extends {} ? { [K in keyof T]?: DeepPartial<T[K]> }
  : Partial<T>;

type KeysOfUnion<T> = T extends T ? keyof T : never;
export type Exact<P, I extends P> = P extends Builtin ? P
  : P & { [K in keyof P]: Exact<P[K], I[K]> } & { [K in Exclude<keyof I, KeysOfUnion<P>>]: never };

function toTimestamp(date: Date): Timestamp {
  const seconds = Math.trunc(date.getTime() / 1_000);
  const nanos = (date.getTime() % 1_000) * 1_000_000;
  return { seconds, nanos };
}

function fromTimestamp(t: Timestamp): Date {
  let millis = (t.seconds || 0) * 1_000;
  millis += (t.nanos || 0) / 1_000_000;
  return new globalThis.Date(millis);
}

function fromJsonTimestamp(o: any): Date {
  if (o instanceof globalThis.Date) {
    return o;
  } else if (typeof o === "string") {
    return new globalThis.Date(o);
  } else {
    return fromTimestamp(Timestamp.fromJSON(o));
  }
}

function longToNumber(int64: { toString(): string }): number {
  const num = globalThis.Number(int64.toString());
  if (num > globalThis.Number.MAX_SAFE_INTEGER) {
    throw new globalThis.Error("Value is larger than Number.MAX_SAFE_INTEGER");
  }
  if (num < globalThis.Number.MIN_SAFE_INTEGER) {
    throw new globalThis.Error("Value is smaller than Number.MIN_SAFE_INTEGER");
  }
  return num;
}

function isSet(value: any): boolean {
  return value !== null && value !== undefined;
}

export interface MessageFns<T> {
  encode(message: T, writer?: BinaryWriter): BinaryWriter;
  decode(input: BinaryReader | Uint8Array, length?: number): T;
  fromJSON(object: any): T;
  toJSON(message: T): unknown;
  create<I extends Exact<DeepPartial<T>, I>>(base?: I): T;
  fromPartial<I extends Exact<DeepPartial<T>, I>>(object: I): T;
}
